<?php if($can_manage&&$dependency_total===0):?><div class="collapse mb-4" id="delete-project"><div class="card border-danger"><div class="card-body"><h2 class="h5 text-danger">Permanently delete this project</h2><p>This project has no BOQs, rate observations, source documents, or metrics. Deletion cannot be undone and does not delete any master data.</p><?=form_open('projects/'.$project->project_id.'/delete')?><label class="form-label" for="confirmation">Enter <strong><?=html_escape($project->project_code)?></strong> to confirm</label><div class="d-flex flex-wrap gap-2"><input class="form-control" id="confirmation" name="confirmation" maxlength="50" required autocomplete="off"><button class="btn btn-danger" type="submit">Permanently Delete Project</button></div><?=form_close()?></div></div></div><?php elseif($can_manage):?><div class="alert alert-info"><strong>Permanent deletion unavailable:</strong> this project has <?=number_format($dependencies->boqs)?> BOQ(s), <?=number_format($dependencies->rates)?> rate observation(s), <?=number_format($dependencies->documents)?> source document(s), and <?=number_format($dependencies->metrics)?> metric(s). Use deactivation to preserve governed history.</div><?php endif;?>
