<div class="card shadow-sm"><div class="card-header"><h2 class="card-title mb-0">Cost Item Rate Observations</h2></div><div class="card-body"><div class="table-responsive"><table class="table table-striped master-data-table"><thead><tr><th>Cost Item</th><th>Revision</th><th>Type</th><th>Rate</th><th>Date</th><th>Location</th><th>Source</th><th>Validation</th></tr></thead><tbody><?php foreach($observations as$r):?><tr><td><?=html_escape($r->enterprise_cost_code?:$r->standard_item_name?:'—')?></td><td><?=html_escape($r->revision_no?:'—')?></td><td><?=html_escape($r->rate_type?:'—')?></td><td><?=number_format($r->unit_rate,2)?></td><td><?=$r->rate_date?html_escape(date('d-M-Y',strtotime($r->rate_date))):'—'?></td><td><?=html_escape($r->location_reference?:'—')?></td><td><?=html_escape($r->source_document?:$r->source_system?:'—')?></td><td><?=html_escape($r->validation_status?:'—')?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$observations):?><p class="text-body-secondary mb-0">No cost-item rate observations reference this project.</p><?php endif;?></div></div>
